static const size_t fs_source_bytes_len = 31742;

static int ensure_dir(const char *path)
{
  struct stat st;
  if (stat(path, &st) == 0) {
    if (S_ISDIR(st.st_mode)) {
      return 0;
    }
    fprintf(stderr, "error: not a directory: %s\n", path);
    return -1;
  }
  if (mkdir(path, 0755) != 0 && errno != EEXIST) {
    fprintf(stderr, "error: mkdir %s: %s\n", path, strerror(errno));
    return -1;
  }
  return 0;
}

static int ensure_emit_dir(const char *root)
{
  char p[4096];
  if ((size_t)snprintf(p, sizeof p, "%s/src", root) >= sizeof p) {
    fprintf(stderr, "error: path too long (src)\n");
    return -1;
  }
  if (ensure_dir(p) != 0) return -1;
  if ((size_t)snprintf(p, sizeof p, "%s/src/systems", root) >= sizeof p) {
    fprintf(stderr, "error: path too long (systems)\n");
    return -1;
  }
  if (ensure_dir(p) != 0) return -1;
  if ((size_t)snprintf(p, sizeof p, "%s/src/systems/emit", root) >= sizeof p) {
    fprintf(stderr, "error: path too long (emit)\n");
    return -1;
  }
  return ensure_dir(p);
}

static int ensure_out_dir(const char *root)
{
  char p[4096];
  if ((size_t)snprintf(p, sizeof p, "%s/out", root) >= sizeof p) {
    fprintf(stderr, "error: path too long (out)\n");
    return -1;
  }
  if (ensure_dir(p) != 0) return -1;
  if ((size_t)snprintf(p, sizeof p, "%s/out/freestanding-c", root) >= sizeof p) {
    fprintf(stderr, "error: path too long (out/freestanding-c)\n");
    return -1;
  }
  return ensure_dir(p);
}

static int write_bytes(const char *path, const unsigned char *data, size_t n)
{
  FILE *f = fopen(path, "wb");
  size_t w;
  if (!f) {
    fprintf(stderr, "error: open %s: %s\n", path, strerror(errno));
    return -1;
  }
  w = fwrite(data, 1, n, f);
  if (w != n) {
    fprintf(stderr, "error: short write %s (%zu of %zu)\n", path, w, n);
    fclose(f);
    return -1;
  }
  if (fclose(f) != 0) {
    fprintf(stderr, "error: close %s: %s\n", path, strerror(errno));
    return -1;
  }
  return 0;
}

int main(int argc, char **argv)
{
  const char *root = (argc > 1 && argv[1] && argv[1][0]) ? argv[1] : ".";
  char path_h[4096];
  char path_c[4096];
  char path_oh[4096];
  char path_oc[4096];
  char path_readme[4096];
  printf("== SLAKE_PRODUCT_WIRE_FS_WRITE_TOOL_V0: freestanding product-wire write (host-cc)\n");
  printf("  host: HOST-PRODUCT-WIRE-FS-WRITE-TOOL / surface: PRODUCT-WIRE-FS-WRITE-TOOL\n");
  printf("  package: dual-eq freestanding dialect (embedded; CapableWriteHc)\n");
  printf("  honest: not Lake-built CapableRegenerate ELF; StillUsesLake remains\n");
  if (ensure_emit_dir(root) != 0) {
    return 1;
  }
  if (ensure_out_dir(root) != 0) {
    return 1;
  }
  if ((size_t)snprintf(path_readme, sizeof path_readme,
        "%s/out/freestanding-c/README.md", root) >= sizeof path_readme) {
    fprintf(stderr, "error: README path too long\n");
    return 1;
  }
  {
    FILE *rf = fopen(path_readme, "rb");
    if (!rf) {
      fprintf(stderr, "error: missing Out README (release marker): %s\n", path_readme);
      return 1;
    }
    fclose(rf);
  }
  if ((size_t)snprintf(path_h, sizeof path_h,
        "%s/src/systems/emit/slake_freestanding.h", root) >= sizeof path_h) {
    fprintf(stderr, "error: header path too long\n");
    return 1;
  }
  if ((size_t)snprintf(path_c, sizeof path_c,
        "%s/src/systems/emit/slake_freestanding.c", root) >= sizeof path_c) {
    fprintf(stderr, "error: source path too long\n");
    return 1;
  }
  if (write_bytes(path_h, fs_header_bytes, fs_header_bytes_len) != 0) {
    return 1;
  }
  if (write_bytes(path_c, fs_source_bytes, fs_source_bytes_len) != 0) {
    return 1;
  }
  if ((size_t)snprintf(path_oh, sizeof path_oh,
        "%s/out/freestanding-c/slake_freestanding.h", root) >= sizeof path_oh) {
    fprintf(stderr, "error: Out header path too long\n");
    return 1;
  }
  if ((size_t)snprintf(path_oc, sizeof path_oc,
        "%s/out/freestanding-c/slake_freestanding.c", root) >= sizeof path_oc) {
    fprintf(stderr, "error: Out source path too long\n");
    return 1;
  }
  if (write_bytes(path_oh, fs_header_bytes, fs_header_bytes_len) != 0) {
    return 1;
  }
  if (write_bytes(path_oc, fs_source_bytes, fs_source_bytes_len) != 0) {
    return 1;
  }
  printf("GREEN SLAKE_PRODUCT_WIRE_FS_WRITE_TOOL_V0: wrote freestanding wire + install Out\n");
  printf("  wrote: %s (%zu bytes)\n", path_h, (size_t)fs_header_bytes_len);
  printf("  wrote: %s (%zu bytes)\n", path_c, (size_t)fs_source_bytes_len);
  printf("  installed: %s\n", path_oh);
  printf("  installed: %s\n", path_oc);
  printf("  greppable: PRODUCT-WIRE-FS-WRITE-TOOL, SLAKE_EMIT_FREESTANDING_C_V0, HOST-EMIT-SSOT\n");
  return 0;
}
